// The plain `nish` entry, which neither build may pick: a native build asks
// `nish-i32` first and a wasm32 build `nish-wasm32` first. It reads the
// environment too, so the wasm32 build would refuse it, and its answer would
// move the native exit code.
import { getenv } from "nish:process";

export const seed = (): i32 => (getenv("NISH_S6_UNSET_VARIABLE") === null ? 1 : 2);
